```csharp
/*
    AudioSourceListerWindow.cs
    --------------------------
    This Unity editor script creates an editor window that lists all AudioSources in the current scene
    and provides buttons to play each one directly from the window.

    Generated by GPT-4.1 (OpenAI), June 2024
*/

using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.Collections.Generic;

public class AudioSourceListerWindow : EditorWindow
{
    // Cached list of AudioSources in the scene
    private List<AudioSource> audioSources = new List<AudioSource>();

    // Used to indicate if the list should be refreshed (i.e., when scene changes)
    private Vector2 scrollPosition;

    // Add menu item to open this Editor window
    [MenuItem("Window/Audio Source Lister")]
    public static void ShowWindow()
    {
        GetWindow<AudioSourceListerWindow>("Audio Source Lister");
    }

    // Draws the Editor window contents
    private void OnGUI()
    {
        // Window title
        GUILayout.Label("List of AudioSources in Scene", EditorStyles.boldLabel);

        // Button to refresh the list
        if (GUILayout.Button("Refresh List"))
        {
            RefreshAudioSourceList();
        }

        // Only allow playback in Editor (not while in Playmode or transitioning)
        bool canPlay = !EditorApplication.isPlayingOrWillChangePlaymode;

        // Display warning if not allowed
        if (!canPlay)
        {
            EditorGUILayout.HelpBox("Audio can only be previewed in Edit Mode.", MessageType.Warning);
        }

        // Scrollable list of AudioSources
        scrollPosition = EditorGUILayout.BeginScrollView(scrollPosition);

        if (audioSources.Count == 0)
        {
            EditorGUILayout.LabelField("No AudioSources found in the current scene.");
        }
        else
        {
            // Enumerate all found AudioSources
            foreach (var source in audioSources)
            {
                if (source == null)
                    continue;

                EditorGUILayout.BeginHorizontal();

                // Show GameObject name and AudioClip name (if assigned)
                EditorGUILayout.ObjectField(source.gameObject.name, source.gameObject, typeof(GameObject), true);

                var clip = source.clip;
                string clipName = clip != null ? clip.name : "(No Clip)";
                EditorGUILayout.LabelField("Clip: " + clipName, GUILayout.Width(150));

                // Button to play the AudioSource (only in Edit mode)
                GUI.enabled = canPlay && clip != null;
                if (GUILayout.Button("Play", GUILayout.Width(50)))
                {
                    PlayClipInEditor(source);
                }

                // Optional: Button to stop all previews
                if (GUILayout.Button("Stop All", GUILayout.Width(65)))
                {
                    StopAllPreviewClips();
                }
                GUI.enabled = true;

                EditorGUILayout.EndHorizontal();
            }
        }

        EditorGUILayout.EndScrollView();
    }

    // On window enable, refresh list and listen to scene changes
    private void OnEnable()
    {
        RefreshAudioSourceList();
        EditorSceneManager.sceneOpened += OnSceneOpened;
        EditorSceneManager.sceneClosed += OnSceneClosed;
    }

    // On window disable, stop listening to events
    private void OnDisable()
    {
        EditorSceneManager.sceneOpened -= OnSceneOpened;
        EditorSceneManager.sceneClosed -= OnSceneClosed;
    }

    // When a new scene is opened, refresh the list
    private void OnSceneOpened(UnityEngine.SceneManagement.Scene scene, OpenSceneMode mode)
    {
        RefreshAudioSourceList();
    }

    // When a scene is closed, refresh the list
    private void OnSceneClosed(UnityEngine.SceneManagement.Scene scene)
    {
        RefreshAudioSourceList();
    }

    // Finds and updates the list of all AudioSources in the current scene
    private void RefreshAudioSourceList()
    {
        // Find all AudioSource objects in the scene, including inactive ones
        audioSources = new List<AudioSource>(FindObjectsOfType<AudioSource>(true));
        Repaint();
    }

    // Plays the AudioClip of the given AudioSource in the editor
    private void PlayClipInEditor(AudioSource source)
    {
        if (source != null && source.clip != null)
        {
            // Use UnityEditor internal utility to play clip in editor
            UnityEditor.EditorUtility.PlayClip(source.clip, 0, false);
        }
    }

    // Stops all audio clips currently previewing in the editor
    private void StopAllPreviewClips()
    {
        UnityEditor.EditorUtility.StopAllPreviewClips();
    }
}
```

Certainly! Below is a simple implementation of a Node.js CRUD REST API to manage employee data using Express and in-memory storage (for demonstration). You can easily swap out the in-memory array for MongoDB, MySQL, or another DB as needed.

---

### 1. Setup

First, initialize your Node.js project and install [Express](https://expressjs.com):

```bash
npm init -y
npm install express
```

---

### 2. app.js

Create a file named `app.js` with the following code:

```javascript
const express = require('express');
const app = express();
const port = 3000;

// Middleware to parse JSON bodies
app.use(express.json());

// In-memory "database" for employee records
let employees = [];
let nextId = 1; // Auto-increment employee ID

// --- CRUD ROUTES ---

// Create - Add a new employee
app.post('/employees', (req, res) => {
    const { name, position, department, email } = req.body;
    if (!name || !position || !department || !email) {
        return res.status(400).json({ error: 'Missing employee fields.' });
    }
    const newEmployee = { id: nextId++, name, position, department, email };
    employees.push(newEmployee);
    res.status(201).json(newEmployee);
});

// Read - Get all employees
app.get('/employees', (req, res) => {
    res.json(employees);
});

// Read - Get employee by ID
app.get('/employees/:id', (req, res) => {
    const emp = employees.find(e => e.id === parseInt(req.params.id));
    if (!emp) return res.status(404).json({ error: 'Employee not found.' });
    res.json(emp);
});

// Update - Update employee by ID
app.put('/employees/:id', (req, res) => {
    const emp = employees.find(e => e.id === parseInt(req.params.id));
    if (!emp) return res.status(404).json({ error: 'Employee not found.' });

    const { name, position, department, email } = req.body;
    if (!name && !position && !department && !email) {
        return res.status(400).json({ error: 'No updated fields provided.' });
    }

    if (name) emp.name = name;
    if (position) emp.position = position;
    if (department) emp.department = department;
    if (email) emp.email = email;

    res.json(emp);
});

// Delete - Remove employee by ID
app.delete('/employees/:id', (req, res) => {
    const index = employees.findIndex(e => e.id === parseInt(req.params.id));
    if (index === -1) return res.status(404).json({ error: 'Employee not found.' });
    const removed = employees.splice(index, 1);
    res.json({ message: 'Employee deleted.', employee: removed[0] });
});

// Start server
app.listen(port, () => {
    console.log(`Employee API running at http://localhost:${port}`);
});
```

---

### 3. Usage (Example Requests)

- **Create Employee:**  
  `POST /employees` with JSON body  
  `{ "name": "Alice", "position": "Developer", "department": "IT", "email": "alice@example.com" }`

- **Get All Employees:**  
  `GET /employees`

- **Get One Employee:**  
  `GET /employees/1`

- **Update Employee:**  
  `PUT /employees/1` with JSON body  
  `{ "position": "Senior Developer" }`

- **Delete Employee:**  
  `DELETE /employees/1`

Use [Postman](https://www.postman.com/) or `curl` to test these endpoints.

---

### 4. Notes

- This uses an in-memory array for employee data; data will reset on server restart.
- For production, use a database and proper request validation.
- To run the app:  
  ```bash
  node app.js
  ```

