Certainly! Below is an example of a Metal compute kernel for applying a Gaussian blur to an image, followed by an explanation of how the code safely handles edge pixels to avoid out-of-bounds memory accesses.

---

### Metal Compute Kernel for Gaussian Blur

```metal
#include <metal_stdlib>
using namespace metal;

constant float gaussianKernel[5] = {0.06136, 0.24477, 0.38774, 0.24477, 0.06136}; // 5-element 1D kernel

kernel void gaussianBlur2D(
    texture2d<float, access::read>  inTexture  [[ texture(0) ]],
    texture2d<float, access::write> outTexture [[ texture(1) ]],
    uint2 gid [[ thread_position_in_grid ]])
{
    // Get image size
    uint width  = inTexture.get_width();
    uint height = inTexture.get_height();

    // Check if the current thread is outside image bounds
    if (gid.x >= width || gid.y >= height) {
        return;
    }

    // Accumulate blurred color
    float4 color = float4(0.0);
    float kernelSum = 0.0;

    // Kernel radius (for a 5x5 kernel it's 2)
    int radius = 2;

    // Apply Gaussian blur (separable: horizontal + vertical)
    for (int y = -radius; y <= radius; y++) {
        for (int x = -radius; x <= radius; x++) {
            int sampleX = int(gid.x) + x;
            int sampleY = int(gid.y) + y;

            // Clamp sample coordinates to edge (to avoid out-of-bounds)
            sampleX = clamp(sampleX, 0, int(width) - 1);
            sampleY = clamp(sampleY, 0, int(height) - 1);

            float kernelWeight = gaussianKernel[x + radius] * gaussianKernel[y + radius];
            float4 sample = inTexture.read(uint2(sampleX, sampleY));
            color += sample * kernelWeight;
            kernelSum += kernelWeight;
        }
    }

    // Normalize and write output
    outTexture.write(color / kernelSum, gid);
}
```

---

### Memory Safety and Bounds Explanation

This kernel avoids memory errors and out-of-bounds accesses in two main ways:

1. **Grid Position Check:**
   - Before doing any processing, the kernel checks if the `gid` (the current pixel coordinates) is outside the image's bounds (`gid.x >= width` or `gid.y >= height`). If so, the thread exits immediately and does no work.

2. **Edge Clamping for Sampling:**
   - When applying the Gaussian blur, the filter needs to sample neighboring pixels. Near the image edges, some neighbors might fall outside the image.
   - To prevent reading outside the image, the kernel clamps the computed sample coordinates using:
     ```
     sampleX = clamp(sampleX, 0, int(width) - 1);
     sampleY = clamp(sampleY, 0, int(height) - 1);
     ```
     This ensures that if the blur kernel wants to sample a pixel before the start of the row (e.g., `gid.x + x < 0`) or after the end (`gid.x + x >= width`), it will instead use the nearest valid edge pixel, never going outside bounds.

By clamping accesses and checking thread positions, the kernel robustly handles all image pixels, including those at the edges, and guarantees no out-of-bounds memory errors occur.

Below is a Terraform module to create an **API Gateway (HTTP API)** that pushes direct REST POST requests into **DynamoDB** using an **AWS service integration** (no custom Lambda, just direct integration).

This solution leverages **API Gateway’s direct integration with DynamoDB** using AWS service proxy, meaning POST requests are directly turned into `PutItem` operations in DynamoDB.

---

## Files/Structure

```
api-gw-dynamodb/
├── main.tf
├── variables.tf
├── outputs.tf
```

---

## `variables.tf`

```hcl
variable "table_name" {
  description = "DynamoDB table name"
  type        = string
}

variable "region" {
  description = "AWS region"
  type        = string
}

variable "api_name" {
  description = "API Gateway HTTP API name"
  type        = string
  default     = "api-gw-dynamodb"
}

variable "partition_key" {
  description = "DynamoDB partition key"
  type        = string
}
```

---

## `main.tf`

```hcl
provider "aws" {
  region = var.region
}

resource "aws_apigatewayv2_api" "rest" {
  name          = var.api_name
  protocol_type = "HTTP"
}

resource "aws_apigatewayv2_integration" "ddb" {
  api_id                 = aws_apigatewayv2_api.rest.id
  integration_type       = "AWS_PROXY"
  integration_uri        = "arn:aws:apigateway:${var.region}:dynamodb:action/PutItem"
  integration_method     = "POST"
  payload_format_version = "1.0"
  credentials_arn        = aws_iam_role.apigw_ddb_role.arn

  request_templates = {
    "application/json" = jsonencode({
      TableName = var.table_name
      Item = {
        # Map your POST JSON payload fields to DynamoDB attributes here
        "${var.partition_key}" = {
          "S" = "$input.path('$.${var.partition_key}')"
        }
        # Optionally map more fields as needed
        # "field2" = { "S" = "$input.path('$.field2')" }
      }
    })
  }
}

resource "aws_apigatewayv2_route" "post" {
  api_id    = aws_apigatewayv2_api.rest.id
  route_key = "POST /item"
  target    = "integrations/${aws_apigatewayv2_integration.ddb.id}"
}

resource "aws_apigatewayv2_stage" "default" {
  api_id      = aws_apigatewayv2_api.rest.id
  name        = "$default"
  auto_deploy = true
}

# IAM Role and Policy for API Gateway to call DynamoDB
resource "aws_iam_role" "apigw_ddb_role" {
  name = "${var.api_name}-apigw-ddb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = {
        Service = "apigateway.amazonaws.com"
      },
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "ddb_write" {
  role = aws_iam_role.apigw_ddb_role.id
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Action   = [
          "dynamodb:PutItem"
        ],
        Resource = "arn:aws:dynamodb:${var.region}:${data.aws_caller_identity.current.account_id}:table/${var.table_name}"
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

```

---

## `outputs.tf`

```hcl
output "api_endpoint" {
  value = aws_apigatewayv2_api.rest.api_endpoint
  description = "Invoke URL for the REST API"
}
```

---

## Usage Example

```hcl
module "api_gw_ddb" {
  source         = "./api-gw-dynamodb"
  region         = "us-east-1"
  table_name     = "your-table-name"
  api_name       = "my-direct-api"
  partition_key  = "your_partition_key"
}
```

---

## How it Works

- Deploys an HTTP API Gateway.
- Configures a **POST /item** route, integrated directly to DynamoDB’s PutItem operation.
- Expects JSON payloads in the schema:  
  ```json
  { "your_partition_key": "value" }
  ```
  - You can expand the `Item` mapping in `main.tf` to map more fields to the DynamoDB item schema.
- API Gateway assumes an IAM role with “PutItem” permissions on

{
  "haiku": {
    "line_1": "Swift fist through the air,",
    "line_2": "Agony strikes with a gasp—",
    "line_3": "Manhood meets its end."
  }
}

